<?php
use App\Http\Controllers\Website\{PublicWebsiteController,WebsiteAdminController,WebsiteContentController};use Illuminate\Support\Facades\Route;
Route::get('/',[PublicWebsiteController::class,'home'])->name('public.home');Route::get('/berita',[PublicWebsiteController::class,'news'])->name('public.news');Route::get('/berita/{slug}',[PublicWebsiteController::class,'showNews'])->name('public.news.show');
Route::middleware(['auth','active','force-password-change'])->prefix('website')->name('website.')->group(function(){Route::get('/',[WebsiteAdminController::class,'index'])->middleware('permission:website.dashboard.view')->name('index');Route::get('/pengaturan',[WebsiteAdminController::class,'settings'])->middleware('permission:website.settings.view')->name('settings');Route::put('/pengaturan',[WebsiteAdminController::class,'update'])->middleware('permission:website.settings.update')->name('settings.update');Route::get('/preview',[WebsiteAdminController::class,'preview'])->middleware('permission:website.dashboard.view')->name('preview');Route::middleware('permission:website.content.manage')->group(function(){Route::get('/konten/{type}',[WebsiteContentController::class,'index'])->name('content.index');Route::get('/konten/{type}/tambah',[WebsiteContentController::class,'create'])->name('content.create');Route::post('/konten/{type}',[WebsiteContentController::class,'store'])->name('content.store');Route::get('/konten/{type}/{id}/edit',[WebsiteContentController::class,'edit'])->name('content.edit');Route::put('/konten/{type}/{id}',[WebsiteContentController::class,'update'])->name('content.update');Route::delete('/konten/{type}/{id}',[WebsiteContentController::class,'destroy'])->name('content.destroy');});});
